  var employee = this.pullEmployeeFromMeridian(employeeId);
  if (!employee) {
    gs.error('Giving up after retries exhausted');
    return;
  }
  var userSysId = this.createPendingUser(employee);
  this.createOnboardingTasks(userSysId);
}
